def S(sid, name, lat, lon, when, desc, verse, generic=False, approx=False, note=None):
    return {"id": sid, "name": name, "lat": lat, "lon": lon, "when": when, "description": desc, "verse": verse,
            "generic": generic, "approximate": approx, "verse_note": note}


